// Icon app TV Samsung (PNG 512x423) nhúng thẳng trong mã Swift.
// Lý do: file .png trong app iOS bị Xcode đổi sang định dạng Apple (CgBI) -> TV không đọc được;
// đổi đuôi .bin thì Xcode lại không chép vào app. Nhúng vào mã nguồn thì không phụ thuộc bước build nào.
// Tạo lại file này khi đổi icon: base64 của TVApp/tv_app_icon.png (SHA-256 63cc6332e20555f1…).
// ============================================================================

import Foundation

enum TVAppIconData {
    static let base64 = ""
    static var png: Data? { Data(base64Encoded: base64) }
}
